<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { FiltrosReporteAsistencia, ReporteAsistenciaDiariaItem, TotalesReporteAsistencia, TrabajadorReporteAsistencia } from '../interfaces/reporteAsistenciaDiaria.interface'
import { descargarReporteAsistenciaPdf, listarReporteAsistenciaDiaria } from '../services/reporteAsistenciaDiaria'
const now=new Date(),today=now.toISOString().slice(0,10),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`
function monthRange(value:string){const parts=value.split('-').map(Number),y=parts[0]??now.getFullYear(),m=parts[1]??(now.getMonth()+1),safe=`${y}-${String(m).padStart(2,'0')}`,start=`${safe}-01`,last=new Date(y,m,0).toISOString().slice(0,10);return {start,end:last>today?today:last}}
const initial=monthRange(month),filters=reactive<FiltrosReporteAsistencia>({mes:month,fecha_inicio:initial.start,fecha_fin:initial.end,datos_persona_id:null})
const rows=ref<ReporteAsistenciaDiariaItem[]>([]),workers=ref<TrabajadorReporteAsistencia[]>([]),totals=ref<TotalesReporteAsistencia>({bloque_1:0,bloque_2:0,bloques:0,descuento_diario:0})
const page=ref(1),lastPage=ref(1),total=ref(0),from=ref<number|null>(null),to=ref<number|null>(null),loading=ref(false),downloading=ref(false),error=ref('')
const money=(v:number)=>`S/ ${Number(v||0).toFixed(6)}`,date=(v:string)=>new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'),time=(v:string|null)=>v?.slice(0,5)||'—'
const discountClass=(minutes:number)=>minutes<=0?'ok':minutes<=5?'warn':'alert'
function changeMonth(){const r=monthRange(filters.mes);filters.fecha_inicio=r.start;filters.fecha_fin=r.end}
async function load(next=1){loading.value=true;error.value='';try{const r=await listarReporteAsistenciaDiaria(filters,next);rows.value=r.data;workers.value=r.trabajadores_filtro;totals.value=r.totales_pagina;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;from.value=r.from;to.value=r.to}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar el reporte.'}finally{loading.value=false}}
function clear(){const r=monthRange(month);filters.mes=month;filters.fecha_inicio=r.start;filters.fecha_fin=r.end;filters.datos_persona_id=null;load(1)}
async function pdf(){downloading.value=true;error.value='';try{await descargarReporteAsistenciaPdf(filters)}catch(e){error.value=e instanceof Error?e.message:'No se pudo descargar el PDF.'}finally{downloading.value=false}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos">Recursos Humanos</RouterLink> / Reporte diario</nav><header class="hero"><div class="mark">RD</div><div><small>MIA · RR. HH. · CONTROL DE TIEMPOS</small><h1>Reporte por día</h1><p>Marcaciones, horarios, tardanzas y descuentos diarios por bloque.</p></div><strong>{{total}} registros</strong></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Trabajador<select v-model="filters.datos_persona_id"><option :value="null">Todos</option><option v-for="w in workers" :key="w.id" :value="w.id">{{w.codigo_trabajador}} - {{w.nombre_completo}}</option></select></label><label>Mes<input v-model="filters.mes" type="month" @change="changeMonth"></label><label>Fecha inicio<input v-model="filters.fecha_inicio" type="date" :max="today"></label><label>Fecha fin<input v-model="filters.fecha_fin" type="date" :max="today"></label><div><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><div class="export"><button :disabled="downloading" @click="pdf">{{downloading?'Generando PDF…':'Exportar PDF · todo el listado'}}</button></div><section class="card"><div v-if="loading" class="empty">Generando reporte diario…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros para los filtros seleccionados.</div><div v-else class="scroll"><table><thead><tr><th>Fecha</th><th>Trabajador</th><th>DNI</th><th>Horario</th><th>Régimen</th><th>E1</th><th>S1</th><th>Descuento bloque 1</th><th>E2</th><th>S2</th><th>Descuento bloque 2</th><th>Tipo</th><th>Modo tardanza</th><th>Descuento diario</th><th>Origen</th><th>Observación</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{date(r.fecha)}}</td><td><b>{{r.trabajador_codigo}}</b><small>{{r.trabajador_nombre}}</small></td><td>{{r.trabajador_dni}}</td><td>{{r.horario_detalle}}</td><td>{{r.regimen_detalle}}</td><td>{{time(r.entrada_1)}}</td><td>{{time(r.salida_1)}}</td><td><div class="discount" :class="discountClass(r.bloque_1.descuento_minutos)"><b>{{r.bloque_1.descuento_minutos}} min</b><small>{{money(r.bloque_1.monto)}} · tardanza {{r.bloque_1.tardanza_minutos}} min</small></div></td><td>{{time(r.entrada_2)}}</td><td>{{time(r.salida_2)}}</td><td><div class="discount" :class="discountClass(r.bloque_2.descuento_minutos)"><b>{{r.bloque_2.descuento_minutos}} min</b><small>{{money(r.bloque_2.monto)}} · tardanza {{r.bloque_2.tardanza_minutos}} min</small></div></td><td><b>{{r.tipo||'—'}}</b></td><td>{{r.modo_descuento_tardanza}}<small>Tardanza diaria: {{r.tardanza_diaria_minutos}} min</small></td><td><div class="discount" :class="discountClass(r.descuento_diario_minutos)"><b>{{money(r.monto_descuento_diario)}}</b><small>{{r.descuento_diario_minutos}} min descontables</small></div></td><td>{{r.origen||'—'}}</td><td>{{r.observacion||'—'}}</td></tr></tbody></table></div><div class="totals"><div><small>Total bloque 1</small><b>{{money(totals.bloque_1)}}</b></div><div><small>Total bloque 2</small><b>{{money(totals.bloque_2)}}</b></div><div><small>Bloques 1 + 2</small><b>{{money(totals.bloques)}}</b></div><div><small>Descuento diario</small><b>{{money(totals.descuento_diario)}}</b></div></div><footer><small>Mostrando {{from||0}} a {{to||0}} de {{total}}</small><div v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></div></footer></section></div></template>
