totals small{color:#77868d;font-size:.47rem}.totals b{font-size:.58rem}.card footer{display:flex;justify-content:space-between;align-items:center;padding:11px 14px}.card footer>div{display:flex;align-items:center;gap:8px;font-size:.5rem}@media(max-width:950px){.filters{grid-template-columns:1fr 1fr}.totals{grid-template-columns:1fr 1fr}}@media(max-width:550px){.filters,.totals{grid-template-columns:1fr}.hero>strong{display:none}}
</style>
